import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());
    const [requests, setRequests] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    // SAU NÀY THAY THẾ: axios.get('/api/admin/maintenance', { params: { date, month, year } })
    const fetchData = () => {
        setLoading(true);
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && item.month === selectedMonth && item.year === selectedYear
        );
        setTimeout(() => {
            setRequests(filtered);
            setLoading(false);
        }, 300);
    };

    // SAU NÀY THAY THẾ: axios.put(`/api/admin/maintenance/${id}`, { status: newStatus })
    const updateStatus = (id, newStatus) => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const updated = allData.map(req => req.id === id ? { ...req, status: newStatus } : req);
        localStorage.setItem('maintenance_db', JSON.stringify(updated));
        fetchData();
    };

    return (
        <div style={containerStyle}>
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🛠 QUẢN LÝ BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentWrapperStyle}>
                {/* KHỐI TRẮNG RÕ CHO BẢNG DỮ LIỆU */}
                <div style={tableCardStyle}>
                    {loading ? (
                        <div style={loadingText}>ĐANG TRUY XUẤT...</div>
                    ) : requests.length > 0 ? (
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead>
                                <tr style={{ borderBottom: '2px solid #fdf3f3', textAlign: 'left' }}>
                                    <th style={thStyle}>PHÒNG</th>
                                    <th style={thStyle}>SỰ CỐ</th>
                                    <th style={thStyle}>THAO TÁC</th>
                                </tr>
                            </thead>
                            <tbody>
                                {requests.map(req => (
                                    <tr key={req.id} style={{ borderBottom: '1px solid #eee' }}>
                                        <td style={{ padding: '15px', fontWeight: 'bold', fontSize: '20px' }}>{req.room}</td>
                                        <td style={{ padding: '15px' }}>
                                            <div style={{fontWeight:'bold', color: '#333'}}>{req.title}</div>
                                            <div style={{fontSize:'12px', color:'#777'}}>{req.issue}</div>
                                            <div style={{fontSize:'10px', color:'#bbb', marginTop: '4px'}}>{req.time}</div>
                                        </td>
                                        <td style={{ padding: '15px' }}>
                                            <select 
                                                value={req.status} 
                                                onChange={(e) => updateStatus(req.id, e.target.value)}
                                                style={statusSelectStyle(req.status)}
                                            >
                                                <option value="pending">Chờ xử lý</option>
                                                <option value="processing">Đang sửa</option>
                                                <option value="completed">Xong</option>
                                            </select>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    ) : (
                        <div style={emptyAdmin}>📅 Không có yêu cầu nào cho ngày này.</div>
                    )}
                </div>
            </div>
        </div>
    );
};

// Styles đồng bộ
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)', backdropFilter: 'blur(10px)' };
const selectStyle = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold' };
const contentWrapperStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '30px' };
const tableCardStyle = { width: '100%', maxWidth: '900px', height: '90%', backgroundColor: '#fff', borderRadius: '30px', padding: '30px', boxShadow: '0 15px 35px rgba(0,0,0,0.2)', overflowY: 'auto' };
const thStyle = { padding: '15px', color: '#8b5e5e', fontSize: '13px' };
const loadingText = { textAlign: 'center', padding: '100px', fontWeight: 'bold', color: '#8b5e5e' };
const emptyAdmin = { textAlign: 'center', padding: '100px', color: '#999' };
const statusSelectStyle = (s) => ({
    padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer',
    backgroundColor: s==='pending'?'#ffebeb':s==='processing'?'#fff4e5':'#e6f4ea',
    color: s==='pending'?'#e03131':s==='processing'?'#664d03':'#1e7e34'
});

export default QuanLyBaoTri;
